import hashlib, json, os, random, statistics, subprocess
from pathlib import Path
os.sched_setaffinity(0, {0})
engines = {"baseline": "/tmp/jit-pc-cursor-baseline/jit-bench", "candidate": "/home/jason/work/quickjs-jit/target/release/jit-bench"}
script = "/home/jason/work/quickjs-jit/benchmarks/scripts/call-heavy.js"
rows = {mode: [] for mode in ["tier2", "automatic"]}
def run(engine, mode):
    return json.loads(subprocess.check_output([engines[engine], "worker", "--mode", mode, "--script", script], text=True))
for index in range(65):
    for mode in rows:
        order = list(engines) if index % 2 else list(reversed(engines))
        row = {engine: run(engine, mode) for engine in order}
        assert row["baseline"]["checksum"] == row["candidate"]["checksum"]
        assert all(r["native_entries"] == r["native_exits"] for r in row.values())
        if index >= 5: rows[mode].append(row)
summary = {}
for mode, pairs in rows.items():
    a = [r["baseline"]["elapsed_ns"] for r in pairs]
    b = [r["candidate"]["elapsed_ns"] for r in pairs]
    rng = random.Random(20260905)
    boot = []
    for _ in range(10000):
        ids = [rng.randrange(len(pairs)) for _ in pairs]
        boot.append(statistics.median(a[i] for i in ids) / statistics.median(b[i] for i in ids))
    boot.sort()
    summary[mode] = {"speed": statistics.median(a) / statistics.median(b), "ci95": [boot[249], boot[9749]]}
report = {"status": "complete", "workload": "call-heavy", "warmups": 5, "pairs_per_mode": 60, "cpu_affinity": [0], "bootstrap_resamples": 10000, "source_dirty": True, "executables": {k: {"path": v, "sha256": hashlib.sha256(Path(v).read_bytes()).hexdigest()} for k,v in engines.items()}, "driver_source": Path(__file__).read_text(), "script_sha256": hashlib.sha256(Path(script).read_bytes()).hexdigest(), "pairs": rows, "summary": summary}
Path("/tmp/jit-pc-cursor-call-heavy-recheck.json").write_text(json.dumps(report, indent=2)+"\n")
print(json.dumps(summary, indent=2), flush=True)
